import SwiftUI
struct LearnSessionView: View {
 @Environment(LearningStore.self) private var store; @Environment(\.dismiss) private var dismiss
 @State private var index=0; @State private var revealed=false; @State private var selection:Set<Int>=[]; @State private var finished=false; @State private var combo=3; @State private var earnedXP=30
 var body:some View{ZStack{LearnDigitalBackground();NavigationStack{if finished{resultView}else{questionView}}.background(.clear)}.preferredColorScheme(.dark)}
 private var question:StudyQuestion{store.questions[index]}
 private var questionView:some View{VStack(spacing:0){sessionHeader;ScrollView(showsIndicators:false){VStack(spacing:18){topicBadge;questionCard;answerArea}.padding(.horizontal,18).padding(.top,20)};HStack{Label("Серия \(combo)",systemImage:"bolt.fill").foregroundStyle(.orange);Spacer();Button{ }label:{Label("Режим",systemImage:"slider.horizontal.3").foregroundStyle(.cyan)}}.font(.caption.bold()).padding(.horizontal,22).padding(.vertical,12)}.toolbar(.hidden,for:.navigationBar)}
 private var sessionHeader:some View{VStack(spacing:10){HStack{Button{dismiss()}label:{Image(systemName:"xmark").font(.headline).foregroundStyle(.white.opacity(0.75)).frame(width:36,height:36).background(.white.opacity(0.07),in:Circle())};Spacer();Text("\(index+1) / \(store.questions.count)").font(.headline.monospacedDigit()).foregroundStyle(.white);Spacer();Button{}label:{Image(systemName:"gearshape.fill").foregroundStyle(.cyan).frame(width:36,height:36).background(.cyan.opacity(0.1),in:Circle())}};HStack(spacing:5){ForEach(0..<min(store.questions.count,15),id:\.self){i in Capsule().fill(i <= index ? Color.cyan : Color.white.opacity(0.10)).frame(maxWidth:.infinity).frame(height:5).shadow(color:i == index ? .cyan.opacity(0.8):.clear,radius:5)}}}.padding(.horizontal,18).padding(.top,12)}
 private var topicBadge:some View{HStack(spacing:7){Image(systemName:"atom");Text("ХИМИЯ · КИСЛОТЫ").font(.caption.bold())}.foregroundStyle(.cyan).padding(.horizontal,12).padding(.vertical,7).background(.cyan.opacity(0.09),in:Capsule()).overlay(Capsule().stroke(.cyan.opacity(0.25)))}
 private var questionCard:some View{VStack(spacing:14){ZStack{Circle().fill(.cyan.opacity(0.08)).frame(width:66,height:66);Circle().stroke(.cyan.opacity(0.24),lineWidth:1).frame(width:56,height:56);Image(systemName:"flask.fill").font(.title).foregroundStyle(.cyan).shadow(color:.cyan.opacity(0.7),radius:9)};Text(question.prompt).font(.system(size:27,weight:.bold,design:.rounded)).foregroundStyle(.white).multilineTextAlignment(.center).minimumScaleFactor(0.75)}.padding(.horizontal,18).padding(.vertical,22).frame(maxWidth:.infinity).background(.black.opacity(0.20),in:RoundedRectangle(cornerRadius:28)).overlay(RoundedRectangle(cornerRadius:28).stroke(LinearGradient(colors:[.cyan.opacity(0.45),.purple.opacity(0.22)],startPoint:.topLeading,endPoint:.bottomTrailing),lineWidth:1))}
 @ViewBuilder private var answerArea:some View{if question.kind == .reveal || question.kind == .pair{revealAnswer}else{choiceAnswer}}
 private var revealAnswer:some View{VStack(spacing:12){if revealed{Text(question.answer).font(.title2.bold()).foregroundStyle(.mint).padding(18).frame(maxWidth:.infinity).background(.mint.opacity(0.10),in:RoundedRectangle(cornerRadius:20));Text("Как получилось?").font(.subheadline.bold()).foregroundStyle(.white.opacity(0.7));ratingButtons}else{Button{withAnimation(.spring(response:0.35)){revealed=true}}label:{HStack{Image(systemName:"sparkles");Text("ОТКРЫТЬ ОТВЕТ").font(.headline);Spacer();Image(systemName:"chevron.right")}.foregroundStyle(.white).padding(.horizontal,18).frame(height:58).background(LinearGradient(colors:[.cyan.opacity(0.8),.blue.opacity(0.75)],startPoint:.leading,endPoint:.trailing),in:RoundedRectangle(cornerRadius:19))}}}}
 private var choiceAnswer:some View{VStack(spacing:10){ForEach(Array(question.choices.enumerated()),id:\.offset){i,c in Button{toggle(i)}label:{HStack(spacing:12){Text(["A","B","C","D"][min(i,3)]).font(.caption.bold()).foregroundStyle(selection.contains(i) ? .black:.cyan).frame(width:30,height:30).background(selection.contains(i) ? Color.cyan:Color.cyan.opacity(0.10),in:Circle());Text(c).font(.body.weight(.semibold)).foregroundStyle(.white);Spacer();if selection.contains(i){Image(systemName:"checkmark.circle.fill").foregroundStyle(.cyan)}}.padding(.horizontal,14).frame(minHeight:58).background(selection.contains(i) ? Color.cyan.opacity(0.10):Color.white.opacity(0.045),in:RoundedRectangle(cornerRadius:18)).overlay(RoundedRectangle(cornerRadius:18).stroke(selection.contains(i) ? Color.cyan.opacity(0.75):Color.white.opacity(0.10)))}.buttonStyle(.plain)};if revealed{ratingButtons}else{Button{revealed=true}label:{Text("ПРОВЕРИТЬ").font(.headline).foregroundStyle(.white).frame(maxWidth:.infinity).frame(height:54).background(selection.isEmpty ? Color.white.opacity(0.08):Color.blue.opacity(0.8),in:RoundedRectangle(cornerRadius:18))}.buttonStyle(.plain).disabled(selection.isEmpty)}}}
 private var ratingButtons:some View{HStack(spacing:8){rating("НЕ ПОМНЮ",.again,.orange);rating("С ТРУДОМ",.hard,.yellow);rating("ЗНАЮ",.good,.mint)}}
 private func rating(_ title:String,_ value:RecallRating,_ color:Color)->some View{Button{submit(value)}label:{Text(title).font(.system(size:11,weight:.bold)).foregroundStyle(color).frame(maxWidth:.infinity).frame(height:44).background(color.opacity(0.10),in:RoundedRectangle(cornerRadius:14)).overlay(RoundedRectangle(cornerRadius:14).stroke(color.opacity(0.35)))}.buttonStyle(.plain)}
 private var resultView:some View{VStack(spacing:20){Spacer();ZStack{Circle().fill(.cyan.opacity(0.12)).frame(width:150,height:150);Image(systemName:"sparkles").font(.system(size:66)).foregroundStyle(.cyan).shadow(color:.cyan,radius:18)};Text("РАУНД ЗАВЕРШЁН").font(.largeTitle.bold()).foregroundStyle(.white);Text("+\(earnedXP) XP · серия \(combo)").font(.title3.bold()).foregroundStyle(.cyan);Button("ГОТОВО"){dismiss()}.buttonStyle(.borderedProminent).controlSize(.large);Spacer()}.padding()}
 private func toggle(_ i:Int){if question.kind == .singleChoice{selection=[i]}else if selection.contains(i){selection.remove(i)}else{selection.insert(i)}}
 private func submit(_ r:RecallRating){store.record(question:question,rating:r);if r == .good{combo+=1;earnedXP+=10}else if r == .hard{earnedXP+=6}else{combo=0;earnedXP+=3};if index+1<store.questions.count{index+=1;revealed=false;selection=[]}else{finished=true}}
}
private struct LearnDigitalBackground:View{var body:some View{ZStack{LinearGradient(colors:[Color(red:0.015,green:0.025,blue:0.08),Color(red:0.025,green:0.055,blue:0.14),Color(red:0.08,green:0.025,blue:0.16)],startPoint:.topLeading,endPoint:.bottomTrailing).ignoresSafeArea();Circle().fill(.cyan.opacity(0.10)).frame(width:280,height:280).blur(radius:70).offset(x:-150,y:-270);Circle().fill(.purple.opacity(0.12)).frame(width:300,height:300).blur(radius:80).offset(x:160,y:250)}}}
